import{_ as e,c as s,a5 as t,o as r}from"./chunks/framework.DoP1wijR.js";const c=JSON.parse('{"title":"HarmonyOS 鸿蒙应用开发  AI的bug AI来修复","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复 云.md","filePath":"鸿蒙开发技巧/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复 云.md","lastUpdated":1759103215000}'),o={name:"鸿蒙开发技巧/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复/HarmonyOS 鸿蒙应用开发  AI的bug AI来修复 云.md"};function n(i,a,E,A,m,l){return r(),s("div",null,a[0]||(a[0]=[t('<h1 id="harmonyos-鸿蒙应用开发-ai的bug-ai来修复" tabindex="-1">HarmonyOS 鸿蒙应用开发 AI的bug AI来修复 <a class="header-anchor" href="#harmonyos-鸿蒙应用开发-ai的bug-ai来修复" aria-label="Permalink to &quot;HarmonyOS 鸿蒙应用开发  AI的bug AI来修复&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>最近由于开发鸿蒙应用存在巨大的红利，我一直在尝试使用AI工具提效功能开发。不过由于鸿蒙应用更新实在太快，一些AI编码工具稍有不慎，就会在功能实现上绕来绕去，始终无法完美解决。</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/u=2873482909,678648409&amp;fm=253&amp;fmt=auto&amp;app=138&amp;f=JPEG" alt=""></p><h2 id="什么bug" tabindex="-1">什么bug <a class="header-anchor" href="#什么bug" aria-label="Permalink to &quot;什么bug&quot;">​</a></h2><p>比如，我这会想要实现一个简单的阅读进度功能，它的原理是<strong>根据当前页面滚动的距离</strong>除以<strong>页面可以滚动的最大的距离</strong>，从而得出阅读<strong>进度的百分比</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阅读进度的百分比 = 当前页面滚动的距离  /  页面可以滚动最大的距离</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这部分代码在HarmonyOS中，结合AI工具实现的话， AI编辑工具死活不知道如何获取页面最大的距离，这个也怪它，要知道鸿蒙开发官网的文档都不是服务器渲染的，也就是你直接给ai一个网址，它是无法直接读出里面具体的代码的。</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250901230046423.png" alt=""></p><p>然后我的AI就是一直乱输出代码了，甚至做出了假设页面最大滚动距离为 1500 的<strong>离谱操作</strong>。</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250901230815015.png" alt=""></p><hr><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250901230828030.png" alt=""></p><hr><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250901230837430.png" alt=""></p><hr><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><p>针对这个情况，解决思路如下：</p><ol><li>直接向AI工具提供关键代码，并清晰描述问题</li><li>但要实现这一点，首先需要知道正确的关键代码是什么</li></ol><p>关键在于使用另一个AI工具——<strong>ima 鸿蒙应用开发知识库</strong>。这是我基于鸿蒙应用API20搭建的知识库，你可以通过自然语言查询获取信息。由于我提前导入了鸿蒙官网1万多个API20文档，它给出的答案相对准确，我最终就是基于它提供的代码完成了需求。</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250901230546619.png" alt=""></p><hr><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250901230608827.png" alt=""></p><hr><p>那么最后我就拿着这段代码喂给ai，结果一次就把功能实现完毕了 ！</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250901230902442.png" alt=""></p><hr><h2 id="最终效果" tabindex="-1">最终效果 <a class="header-anchor" href="#最终效果" aria-label="Permalink to &quot;最终效果&quot;">​</a></h2><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/PixPin_2025-09-01_23-10-11.gif" alt=""></p><h2 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h2><ol><li><p>ima 知识库</p><blockquote><p>【ima知识库】鸿蒙应用知识库 API20 <a href="https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7" target="_blank" rel="noreferrer">https://ima.qq.com/wiki/?shareId=b0d462ae618a0fefb5b714565cad3dd4a60411a435d5f81db51670ffb2ff3ad7</a></p></blockquote></li><li><p>扫码使用</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/zhiuik.png" alt=""></p></li></ol><h2 id="以往文章" tabindex="-1">以往文章 <a class="header-anchor" href="#以往文章" aria-label="Permalink to &quot;以往文章&quot;">​</a></h2><ul><li><a href="https://mp.weixin.qq.com/s/sMd0CGe54T2Eya8dPaEn2A" target="_blank" rel="noreferrer">懂你的HarmonyOS知识库更新了，已经来到10970个文档了</a></li><li><a href="https://mp.weixin.qq.com/s/tmchdy91UKmAtwwJr-PQ-A" target="_blank" rel="noreferrer">最新 HarmonyOS API 20 知识库 重磅推出</a></li></ul><h2 id="近期活动" tabindex="-1">近期活动 <a class="header-anchor" href="#近期活动" aria-label="Permalink to &quot;近期活动&quot;">​</a></h2><p>最近想要考取HarmonyOS基础或高级证书的同学，可以点击这个链接<a href="https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&amp;ha_sourceId=89000248" target="_blank" rel="noreferrer">加入我的班级</a>，考取成功有机会获得鸿蒙礼盒一份。</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/image-20250822223258675.png" alt=""></p><h2 id="联系我" tabindex="-1">联系我 <a class="header-anchor" href="#联系我" aria-label="Permalink to &quot;联系我&quot;">​</a></h2><p>可以加我微信，带你了解更多HarmonyOS相关的资讯。</p><p><img src="https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/HarmonyOS%20%E9%B8%BF%E8%92%99%E5%BA%94%E7%94%A8%E5%BC%80%E5%8F%91%20%20AI%E7%9A%84bug%20AI%E6%9D%A5%E4%BF%AE%E5%A4%8D/assets/wanshaoweixin.jpg" alt=""></p>',39)]))}const h=e(o,[["render",n]]);export{c as __pageData,h as default};
